export type ToolCallLocation = {
  readonly path: AbsolutePath;
  readonly line?: number | null;
  readonly _meta?: { readonly [x: string]: Schema.Json } | null;
};
export const ToolCallLocation = Schema.Struct({
  path: Schema.suspend((): Schema.Codec<AbsolutePath> => AbsolutePath).annotate({
    description: "The absolute file path being accessed or modified.",
  }),
  line: Schema.optionalKey(
    Schema.Union([
      Schema.Number.annotate({
        description:
          "Optional 1-based line number within the file. Omitted and `null` are equivalent and\nmean no specific line. `0` is invalid.",
        format: "uint32",
      })
        .check(Schema.isInt().annotate({ expected: "an integer" }))
        .check(
          Schema.isGreaterThanOrEqualTo(1).annotate({
            expected: "a value greater than or equal to 1",
          }),
        ),
      Schema.Null,
    ]),
  ),
  _meta: Schema.optionalKey(
    Schema.Union([
      Schema.Record(Schema.String, Schema.Json.annotate({ expected: "JSON value" })).annotate({
        description:
          "The _meta property is reserved by ACP to allow Clients and Agents to attach additional\nmetadata to their interactions. Omitted and `null` are equivalent and mean no metadata.\nImplementations MUST NOT assign meaning to keys they do not recognize.\n\nSee protocol docs: [Extensibility](https://agentclientprotocol.com/protocol/v2/draft/extensibility)",
      }),
      Schema.Null,
    ]),
  ),
}).annotate({
  description:
    'A file location being accessed or modified by a tool.\n\nEnables Clients to implement "follow-along" features that track\nwhich files the Agent is working with in real-time.\n\nSee protocol docs: [Following the Agent](https://agentclientprotocol.com/protocol/v2/draft/tool-calls#following-the-agent)',
  identifier: "ToolCallLocation",
});

export type SessionInfo = {
  readonly sessionId: SessionId;
  readonly cwd: AbsolutePath;
  readonly additionalDirectories?: ReadonlyArray<AbsolutePath>;
  readonly title?: string | null;
  readonly updatedAt?: string | null;
  readonly archived?: boolean | null;
  readonly _meta?: { readonly [x: string]: Schema.Json } | null;
};
export const SessionInfo = Schema.Struct({
  sessionId: Schema.suspend((): Schema.Codec<SessionId> => SessionId).annotate({
    description: "Unique identifier for the session",
  }),
  cwd: Schema.suspend((): Schema.Codec<AbsolutePath> => AbsolutePath).annotate({
    description: "The working directory for this session. Must be an absolute path.",
  }),
  additionalDirectories: Schema.optionalKey(
    Schema.Array(AbsolutePath).annotate({
      description:
        "Additional workspace roots reported for this session. Each path MUST be absolute.\n\nWhen present, this is the complete ordered additional-root list reported\nby the Agent. Omitted and empty values are equivalent: the response\nreports no additional roots.",
    }),
  ),
  title: Schema.optionalKey(
    Schema.Union([
      Schema.String.annotate({
        description:
          "Human-readable title for the session\n\nOmitted and `null` are equivalent and mean no title is provided.",
      }),
      Schema.Null,
    ]),
  ),
  updatedAt: Schema.optionalKey(
    Schema.Union([
      Schema.String.annotate({
        description:
          "RFC 3339 timestamp of last activity.\n\nOmitted and `null` are equivalent and mean the last activity time is not reported.",
        format: "date-time",
      }),
      Schema.Null,
    ]),
  ),
  archived: Schema.optionalKey(
    Schema.Union([
      Schema.Boolean.annotate({
        description:
          "**UNSTABLE**\n\nThis capability is not part of the spec yet, and may be removed or changed at any point.\n\nWhether the session is archived.\n\nOptional. Omitted and `null` are equivalent and mean the archive state is not reported.\nAgents that advertise the `session.archive` capability MUST include it on every listed session.",
      }),
      Schema.Null,
    ]),
  ),
  _meta: Schema.optionalKey(
    Schema.Union([
      Schema.Record(Schema.String, Schema.Json.annotate({ expected: "JSON value" })).annotate({
        description:
          "The _meta property is reserved by ACP to allow Clients and Agents to attach additional\nmetadata to their interactions. Omitted and `null` are equivalent and mean no metadata.\nImplementations MUST NOT assign meaning to keys they do not recognize.\n\nSee protocol docs: [Extensibility](https://agentclientprotocol.com/protocol/v2/draft/extensibility)",
      }),
      Schema.Null,
    ]),
  ),
}).annotate({
  description: "Information about a session returned by session/list",
  identifier: "SessionInfo",
});

export type SessionOptionsRequest = {
  readonly cwd: AbsolutePath;
  readonly additionalDirectories?: ReadonlyArray<AbsolutePath>;
  readonly sessionId?: SessionId | null;
  readonly _meta?: { readonly [x: string]: Schema.Json } | null;
};
export const SessionOptionsRequest = Schema.Struct({
  cwd: Schema.suspend((): Schema.Codec<AbsolutePath> => AbsolutePath).annotate({
    description: "The working directory to resolve options for. Must be an absolute path.",
  }),
  additionalDirectories: Schema.optionalKey(
    Schema.Array(AbsolutePath).annotate({
      description:
        "Additional workspace roots to resolve options for. Each path MUST be absolute.\n\nOptional. Omitted and `null` are equivalent to an empty list.",
    }),
  ),
  sessionId: Schema.optionalKey(
    Schema.Union([SessionId, Schema.Null]).annotate({
      description:
        "The session to resolve options for.\n\nOptional. Omitted and `null` are equivalent and mean a new session. When present,\nthe Agent returns what `session/resume` with the same `cwd` and\n`additionalDirectories` would return, with the same `cwd` rules. A session the\nAgent does not know gets `-32002`.",
    }),
  ),
  _meta: Schema.optionalKey(
    Schema.Union([
      Schema.Record(Schema.String, Schema.Json.annotate({ expected: "JSON value" })).annotate({
        description:
          "The _meta property is reserved by ACP to allow Clients and Agents to attach additional\nmetadata to their interactions. Omitted and `null` are equivalent and mean no metadata.\nImplementations MUST NOT assign meaning to keys they do not recognize.\n\nSee protocol docs: [Extensibility](https://agentclientprotocol.com/protocol/v2/draft/extensibility)",
      }),
      Schema.Null,
    ]),
  ),
}).annotate({
  description:
    "**UNSTABLE**\n\nThis capability is not part of the spec yet, and may be removed or changed at any point.\n\nRequest parameters for `session/options`, which returns the config options a session\nwould start with, without creating or resuming a session.\n\nOnly available if the Agent supports the `session.options` capability.\n\n`session/options` MUST NOT create or resume a session, send `session/update`\nnotifications, add an entry to `session/list`, or change an existing session. Agents\nSHOULD NOT connect to MCP servers to answer it. Agents MAY start their runtime to resolve\nthe options. The rules above still hold for it.",
  identifier: "SessionOptionsRequest",
});

